-- Existing Omniqora workspaces become Omniqora product tenants without creating a second tenant record.
SELECT t.id,'omniqora','active',t.created_at
FROM public.tenants t
ON CONFLICT(tenant_id,product_key) DO NOTHING;

-- Existing RRCI entitlements are reflected in the new universal service model.
  tenant_id,service_key,status,quantity,unit_amount_pence,config,activated_at,cancelled_at
)
SELECT e.tenant_id,'omniqora.rrci',
  CASE e.status WHEN 'cancelled' THEN 'cancelled' WHEN 'suspended' THEN 'suspended' ELSE 'active' END,
  1,0,jsonb_build_object('legacyBillingReference',e.billing_reference,'validUntil',e.valid_until),
  CASE WHEN e.status IN ('trial','active') THEN e.updated_at ELSE null END,
  CASE WHEN e.status='cancelled' THEN e.updated_at ELSE null END
FROM public.addon_entitlements e
WHERE e.addon='rrci'
ON CONFLICT(tenant_id,service_key) DO UPDATE SET
  status=excluded.status,config=public.omniqora_tenant_services.config||excluded.config,
  updated_at=now();

COMMIT;
